import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Chart as ChartJS, ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement } from 'chart.js';
import { Pie, Bar } from 'react-chartjs-2';
import { FaChartPie, FaChartBar, FaRocket, FaCheckCircle, FaFire, FaBullseye } from 'react-icons/fa';
import { motion } from 'framer-motion';
import axios from 'axios';

ChartJS.register(ArcElement, Tooltip, Legend, CategoryScale, LinearScale, BarElement);

const ProgressStats = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) fetchData();
    }, [user]);

    const fetchData = async () => {
        try {
            const res = await axios.get(`http://localhost:8081/api/tasks/user/${user.id}`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setTasks(res.data);
            setLoading(false);
        } catch (error) {
            console.error('❌ Failed to fetch:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-[60vh]">
                <div className="text-center">
                    <div className="spinner-border text-indigo-500" role="status" style={{ width: '3rem', height: '3rem' }}>
                        <span className="sr-only">Loading...</span>
                    </div>
                    <p className="text-gray-400 mt-3 text-sm">Loading your analytics...</p>
                </div>
            </div>
        );
    }

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted === true).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

    const javaCompleted = tasks.filter(t => t.javaCompleted === true).length;
    const leetcodeCompleted = tasks.filter(t => t.leetcodeCompleted === true).length;
    const dsaCompleted = tasks.filter(t => t.dsaCompleted === true).length;
    const sqlCompleted = tasks.filter(t => t.sqlCompleted === true).length;
    const projectCompleted = tasks.filter(t => t.projectCompleted === true).length;
    const githubCompleted = tasks.filter(t => t.githubCompleted === true).length;

    const calculateStreak = () => {
        let streak = 0;
        const sorted = [...tasks].sort((a, b) => a.day - b.day);
        for (const task of sorted) {
            if (task.overallCompleted === true) streak++;
            else break;
        }
        return streak;
    };

    const streak = calculateStreak();

    // --- PROFESSIONAL DARK THEME CHART OPTIONS ---
    const chartOptions = {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
            legend: {
                labels: { 
                    color: '#9ca3af', // Light Gray for Dark Mode
                    font: { family: 'Inter, sans-serif', size: 12, weight: '500' },
                    boxWidth: 15,
                    padding: 15
                },
            },
            tooltip: {
                backgroundColor: '#1f2937',
                titleColor: '#f3f4f6',
                bodyColor: '#d1d5db',
                borderColor: '#374151',
                borderWidth: 1,
                padding: 10,
                cornerRadius: 8,
            }
        },
        scales: {
            y: {
                beginAtZero: true,
                grid: { color: '#374151' }, // Dark grid lines
                ticks: { color: '#9ca3af' },
            },
            x: {
                grid: { display: false },
                ticks: { color: '#9ca3af' },
            },
        },
    };

    const pieData = {
        labels: ['Completed ✅', 'Remaining ⏳'],
        datasets: [{
            data: [completedTasks, Math.max(0, totalTasks - completedTasks)],
            backgroundColor: ['#8b5cf6', '#374151'], // Purple vs Dark Gray
            borderWidth: 0,
        }],
    };

    const barData = {
        labels: ['Java', 'LeetCode', 'DSA', 'SQL/API', 'Project', 'GitHub'],
        datasets: [{
            label: 'Tasks Completed',
            data: [javaCompleted, leetcodeCompleted, dsaCompleted, sqlCompleted, projectCompleted, githubCompleted],
            backgroundColor: ['#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ec4899', '#06b6d4'],
            borderRadius: 6,
            barPercentage: 0.6,
        }],
    };

    const statsCards = [
        { label: 'Completion Rate', value: `${completionRate}%`, icon: FaChartPie, color: 'text-purple-400', bg: 'bg-purple-500/10' },
        { label: 'Tasks Done', value: `${completedTasks}/${totalTasks}`, icon: FaCheckCircle, color: 'text-blue-400', bg: 'bg-blue-500/10' },
        { label: 'Streak', value: `${streak} days`, icon: FaFire, color: 'text-orange-400', bg: 'bg-orange-500/10' },
        { label: 'Target', value: '30 days', icon: FaBullseye, color: 'text-pink-400', bg: 'bg-pink-500/10' },
    ];

    return (
        <div className="w-full p-0 pb-10">
            {/* --- PROFESSIONAL HEADER --- */}
            <motion.div 
                initial={{ opacity: 0, y: -20 }} 
                animate={{ opacity: 1, y: 0 }} 
                className="bg-gradient-to-r from-indigo-600 via-purple-600 to-pink-500 rounded-2xl p-8 mb-8 text-white shadow-lg"
            >
                <div className="flex items-center gap-4">
                    <div className="bg-white/20 p-3 rounded-xl backdrop-blur-sm">
                        <FaChartBar size={28} className="text-white" />
                    </div>
                    <div>
                        <h1 className="text-3xl font-bold tracking-tight mb-1">Progress Analytics</h1>
                        <p className="text-indigo-100 text-sm md:text-base font-medium opacity-90">Track your learning journey</p>
                    </div>
                </div>
            </motion.div>

            {/* --- STATS CARDS (Bootstrap se Tailwind me change) --- */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                {statsCards.map((stat, index) => {
                    const Icon = stat.icon;
                    return (
                        <motion.div 
                            key={index} 
                            initial={{ opacity: 0, y: 20 }} 
                            animate={{ opacity: 1, y: 0 }} 
                            transition={{ delay: index * 0.1 }} 
                            className="bg-[#1f2937] border border-gray-800 rounded-2xl p-5 shadow-lg hover:shadow-purple-500/10 transition-all duration-300"
                        >
                            <div className="flex justify-between items-center">
                                <div>
                                    <p className="text-gray-400 text-xs font-medium uppercase tracking-wider mb-1">{stat.label}</p>
                                    <h2 className="text-2xl font-bold text-white">{stat.value}</h2>
                                </div>
                                <div className={`p-3 rounded-xl ${stat.bg}`}>
                                    <Icon className={`${stat.color} text-xl`} />
                                </div>
                            </div>
                        </motion.div>
                    );
                })}
            </div>

            {/* --- CHARTS SECTION --- */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-8">
                <motion.div initial={{ opacity: 0, x: -20 }} animate={{ opacity: 1, x: 0 }} className="bg-[#1f2937] border border-gray-800 rounded-2xl p-6 shadow-lg">
                    <h5 className="text-gray-200 font-semibold text-lg mb-6 flex items-center gap-2">
                        <FaChartPie className="text-purple-400" /> Overall Completion
                    </h5>
                    <div className="h-[250px] flex items-center justify-center relative">
                        <Pie data={pieData} options={chartOptions} />
                    </div>
                    <div className="text-center mt-4 border-t border-gray-800 pt-4">
                        <p className="text-gray-400 text-sm">{completedTasks} of {totalTasks} tasks completed</p>
                        {totalTasks === 0 && <p className="text-yellow-500 text-xs mt-1 font-medium">⚠️ Create tasks in Daily Tracker to start tracking!</p>}
                    </div>
                </motion.div>

                <motion.div initial={{ opacity: 0, x: 20 }} animate={{ opacity: 1, x: 0 }} className="bg-[#1f2937] border border-gray-800 rounded-2xl p-6 shadow-lg">
                    <h5 className="text-gray-200 font-semibold text-lg mb-6 flex items-center gap-2">
                        <FaChartBar className="text-blue-400" /> Task-wise Completion
                    </h5>
                    <div className="h-[250px]">
                        <Bar data={barData} options={chartOptions} />
                    </div>
                    {totalTasks === 0 && <p className="text-yellow-500 text-xs text-center mt-4 font-medium">⚠️ No data to display. Create tasks in Daily Tracker!</p>}
                </motion.div>
            </div>

            {/* --- MOTIVATION SECTION (Modernized) --- */}
            <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="bg-gradient-to-r from-indigo-900/50 via-purple-900/50 to-pink-900/50 border border-gray-700 rounded-2xl p-8 flex flex-col md:flex-row items-center justify-between gap-6 relative overflow-hidden">
                <div className="absolute -top-10 -right-10 text-white/5 text-[150px] font-bold select-none pointer-events-none">🚀</div>
                
                <div className="z-10 text-center md:text-left">
                    <h2 className="text-white font-bold text-2xl mb-2 tracking-tight">Keep Going!</h2>
                    <p className="text-gray-400 max-w-lg">You're making great progress! Consistency is the key to mastering development skills.</p>
                    <div className="flex flex-wrap justify-center md:justify-start gap-2 mt-4">
                        <span className="bg-white/10 text-gray-300 px-3 py-1 rounded-full text-xs font-medium border border-white/10">#CodeEveryday</span>
                        <span className="bg-white/10 text-gray-300 px-3 py-1 rounded-full text-xs font-medium border border-white/10">#NeverGiveUp</span>
                        <span className="bg-white/10 text-gray-300 px-3 py-1 rounded-full text-xs font-medium border border-white/10">#StayConsistent</span>
                    </div>
                </div>
                
                <div className="z-10 bg-purple-500/20 p-4 rounded-full md:mr-8">
                    <FaRocket size={40} className="text-purple-400" />
                </div>
            </motion.div>
        </div>
    );
};

export default ProgressStats;
